def sum_decoded_powers(nums):
    MOD=10**9+7;answer=0
    for encoded in nums:
        body,width=divmod(encoded,10);text=str(body)
        answer=(answer+pow(int(text[:width]),int(text[width:]),MOD))%MOD
    return answer

